@Mapper
interface ProductMapper {
    @Mapping(target = "sku", qualifiedByName = "normalizeSku")
    ProductDto toDto(Product product);

    @Named("normalizeSku")
    default String normalizeSku(String sku) {
        return sku == null ? null : sku.trim().toUpperCase();
    }
}

