// POPRAWNIE: wlasna metoda default obsluguje null ORAZ pusty String
@Mapper
interface ProductMapper {
    @Mapping(target = "category", qualifiedByName = "normalizeCategory")
    ProductDto toDto(Product product);

    @Named("normalizeCategory")
    default String normalizeCategory(String category) {
        return (category == null || category.isBlank()) ? "OGOLNA" : category;
    }
}
